"""Measure source-bound crossing entry order and timing without a legal cutoff."""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT = 'testing__C125751__NRS-484B-250-2__motor_vehicle_driver'
CASES = ('precedence', 'advance', 'timing_below', 'timing_inside', 'timing_above')


def _pair(value, label):
    if (not isinstance(value, list) or len(value) != 2 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in value)):
        raise ValueError(f'{label} must be finite xy')
    return value


def _inside(vertices, bounds):
    xs, ys = zip(*vertices)
    return max(xs) >= bounds[0] and min(xs) <= bounds[2] and max(ys) >= bounds[1] and min(ys) <= bounds[3]


def measure(trace, survey):
    case = trace.get('case_id')
    if case not in {ASSIGNMENT + '__' + suffix for suffix in CASES}:
        raise ValueError('foreign exact timing case')
    if survey.get('cell_id') != 'C125751' or survey.get('crossing_kind') != 'median_opening_roadway_crossing':
        raise ValueError('identified roadway crossing source missing')
    bounds = survey.get('crossing_bounds_xy_m')
    if (not isinstance(bounds, list) or len(bounds) != 4 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in bounds) or
            bounds[0] >= bounds[2] or bounds[1] >= bounds[3]):
        raise ValueError('observed crossing bounds missing')
    if trace.get('map_sha256') != survey.get('opendrive_sha256'):
        raise ValueError('original map source differs')
    roads = survey.get('approach_road_ids')
    if not isinstance(roads, dict) or set(roads) != {'ego', 'other'} or roads['ego'] == roads['other']:
        raise ValueError('different highway approach IDs required')
    if survey.get('public_highway_source') is None:
        raise ValueError('public highway source required')
    if survey.get('governing_device') != 'official_traffic_light':
        raise ValueError('official traffic-light context required')
    ego_direction = _pair(survey.get('ego_direction_xy'), 'ego direction')
    other_origin = _pair(survey.get('other_approach_xy'), 'other approach')
    ego_origin = _pair(survey.get('ego_approach_xy'), 'ego approach')
    vector = [other_origin[i] - ego_origin[i] for i in range(2)]
    cross = ego_direction[0] * vector[1] - ego_direction[1] * vector[0]
    if abs(cross) < 0.01 or math.hypot(*ego_direction) < 0.01:
        raise ValueError('left/right approach geometry ambiguous')
    frames = trace.get('frames')
    if not isinstance(frames, list) or len(frames) != 900:
        raise ValueError('900 original crossing frames required')
    actor_ids = trace.get('actor_ids')
    if not isinstance(actor_ids, dict) or set(actor_ids) != {'ego', 'other'} or actor_ids['ego'] == actor_ids['other']:
        raise ValueError('two distinct original actors required')
    first_frame = first_time = None
    entries = {'ego': None, 'other': None}
    entry_device_states = {'ego': None, 'other': None}
    exits = {'ego': None, 'other': None}
    prior_inside = {'ego': False, 'other': False}
    device_states = set()
    for i, row in enumerate(frames):
        native_frame = row.get('native_frame_id')
        native_time = row.get('native_elapsed_seconds')
        if (row.get('frame') != i or not math.isclose(row.get('time_s', -1), i / 20, abs_tol=1e-5) or
                type(native_frame) is not int or type(native_time) not in (int, float) or
                not math.isfinite(native_time)):
            raise ValueError('original frame/time source join missing')
        if first_frame is None:
            first_frame, first_time = native_frame, native_time
        if native_frame != first_frame + i or not math.isclose(native_time - first_time, i / 20, abs_tol=.002):
            raise ValueError('original Native 20 Hz clock discontinuity')
        state = row.get('governing_device_readback')
        if state not in ('red', 'yellow', 'green', 'flashing', 'inoperative'):
            raise ValueError('original governing device readback missing')
        device_states.add(state)
        for name in ('ego', 'other'):
            actor = row.get(name)
            if not isinstance(actor, dict) or actor.get('id') != actor_ids[name] or actor.get('road_id') != roads[name]:
                raise ValueError('original actor or approach road differs')
            vertices = actor.get('body_vertices_xy_m')
            if not isinstance(vertices, list) or len(vertices) < 4:
                raise ValueError('original actor footprint missing')
            vertices = [_pair(point, 'body vertex') for point in vertices]
            inside = _inside(vertices, bounds)
            if i == 0 and inside:
                raise ValueError('entry not observed from outside crossing')
            if inside and not prior_inside[name] and entries[name] is None:
                entries[name] = {'frame': i, 'native_frame_id': native_frame,
                                 'upper_elapsed_seconds': native_time,
                                 'lower_elapsed_seconds': frames[i-1]['native_elapsed_seconds']}
                entry_device_states[name] = state
            if not inside and prior_inside[name] and exits[name] is None:
                exits[name] = {'frame': i, 'native_frame_id': native_frame,
                               'upper_elapsed_seconds': native_time,
                               'lower_elapsed_seconds': frames[i-1]['native_elapsed_seconds']}
            prior_inside[name] = inside
    if any(value is None for value in entries.values()):
        raise ValueError('both original intersection entries required')
    difference = entries['ego']['upper_elapsed_seconds'] - entries['other']['upper_elapsed_seconds']
    response = 'unresolved_incomplete_exit'
    if exits['other'] is not None:
        response = ('yield_before_entry' if entries['ego']['frame'] >= exits['other']['frame']
                    else 'advance_before_other_exit')
    return {'case_id': case, 'entry_brackets': entries,
            'exit_brackets': exits, 'observed_ego_response': response,
            'ego_minus_other_upper_entry_s': difference,
            'other_approach_side_of_ego': 'right' if cross < 0 else 'left',
            'governing_device_states': sorted(device_states),
            'governing_device_entry_states': entry_device_states,
            'approximately_same_time_judgment': 'unresolved',
            'statutory_applicability': 'unresolved_official_device_exclusion_and_subsection_4',
            'right_of_way_judgment': 'unresolved'}


def measure_sealed(root, manifest_path, survey_path):
    root = Path(root).resolve()
    manifest_path, survey_path = Path(manifest_path), Path(survey_path)
    manifest = json.loads(manifest_path.read_text())
    survey = json.loads(survey_path.read_text())
    if manifest.get('survey_sha256') != hashlib.sha256(survey_path.read_bytes()).hexdigest():
        raise ValueError('original surveyed crossing packet hash differs')
    ref = manifest.get('trace')
    if not isinstance(ref, dict) or not isinstance(ref.get('path'), str):
        raise ValueError('original trace reference required')
    relative = Path(ref['path'])
    if relative.is_absolute() or any(part in ('.', '..') for part in relative.parts):
        raise ValueError('original trace path escapes attempt')
    trace_path = (root / relative).resolve()
    if not trace_path.is_relative_to(root) or not trace_path.is_file():
        raise ValueError('original trace missing')
    raw = trace_path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != ref.get('sha256'):
        raise ValueError('original trace digest differs')
    return measure(json.loads(raw), survey)

"""Capture original median-crossing actor, clock, device and camera sources.

The injected adapter owns CARLA calls. No imported simulator or diagnostic
fixture can stand in for an absent original readback in this boundary.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from entry_timing import ASSIGNMENT, CASES, measure

CAMERAS = ('front', 'rear', 'left', 'right')


def _check_fresh_destination(output, case_id):
    if not output.exists() or not any(output.iterdir()):
        return
    construction_path = output/'construction.json'
    selection_path = output/'candidate-selection.json'
    if not construction_path.is_file() or not selection_path.is_file():
        raise ValueError('refusing to overwrite original crossing attempt')
    construction = json.loads(construction_path.read_text())
    selection = json.loads(selection_path.read_text())
    if construction.get('case_id') != case_id or selection.get('case_id') != case_id:
        raise ValueError('materialized exact case differs')
    if selection.get('construction_sha256') != hashlib.sha256(construction_path.read_bytes()).hexdigest():
        raise ValueError('materialized construction digest differs')
    allowed = {'construction.json', 'candidate-selection.json'}
    for item in construction.get('files', []):
        relative = item.get('path')
        if not isinstance(relative, str) or not relative or Path(relative).is_absolute() or '..' in Path(relative).parts:
            raise ValueError('materialized bundle path invalid')
        path = output/relative
        if path.is_symlink() or not path.is_file() or path.read_text() != item.get('content'):
            raise ValueError('materialized bundle file differs')
        allowed.add(relative)
    observed = {str(path.relative_to(output)) for path in output.rglob('*') if path.is_file()}
    if observed != allowed or any(path.is_symlink() for path in output.rglob('*')):
        raise ValueError('refusing to overwrite original crossing attempt')


def _source_path(root, relative):
    if not isinstance(relative, str) or not relative:
        raise ValueError('original camera source path missing')
    path = Path(relative)
    if path.is_absolute() or any(part in ('.', '..') for part in path.parts):
        raise ValueError('original camera source escapes attempt')
    target = (root/path).resolve()
    if not target.is_relative_to(root.resolve()) or not target.is_file():
        raise ValueError('original camera source missing')
    return target


def capture(adapter, survey_path, survey_sha256, map_source_path, case_id, output):
    """Run one 45 s source-gated original Native attempt.

    Adapter: verify_map, spawn_actors, configure_cameras, request_controls,
    tick, actor_snapshot, signal_readback, camera_frame, emergency_stop,
    destroy. Every saved field comes from post-tick readback.
    """
    if case_id not in {ASSIGNMENT+'__'+suffix for suffix in CASES}:
        raise ValueError('foreign exact timing case')
    output = Path(output)
    _check_fresh_destination(output, case_id)
    raw_survey = Path(survey_path).read_bytes()
    if hashlib.sha256(raw_survey).hexdigest() != survey_sha256:
        raise ValueError('original crossing survey hash differs')
    survey = json.loads(raw_survey)
    raw_map = Path(map_source_path).read_bytes()
    if hashlib.sha256(raw_map).hexdigest() != survey.get('opendrive_sha256'):
        raise ValueError('original OpenDRIVE source hash differs')
    if survey.get('cell_id') != 'C125751' or survey.get('crossing_kind') != 'median_opening_roadway_crossing':
        raise ValueError('original median roadway crossing identity required')
    if survey.get('governing_device') != 'official_traffic_light':
        raise ValueError('original governing traffic light required')
    adapter.verify_map(survey, raw_map)
    handles = {}
    camera_bound = False
    runtime_capture_bound = False
    completed = False
    rows = []
    media = {name: [] for name in CAMERAS}
    first_frame = first_time = None
    output.mkdir(parents=True, exist_ok=True)
    try:
        from scenario_pipeline.worker_exchange.native_output import FrameMap
        handles = adapter.spawn_actors(survey, case_id)
        if not isinstance(handles, dict) or set(handles) != {'ego', 'other'}:
            raise ValueError('two original crossing actors required')
        adapter.configure_cameras(handles['ego'], CAMERAS, fps=20, output=output)
        camera_bound = True
        if hasattr(adapter, 'start_runtime_capture'):
            adapter.start_runtime_capture(handles['ego'], case_id)
            runtime_capture_bound = True
        with FrameMap(output/'video_frames.jsonl') as frame_map:
            for index in range(900):
                adapter.request_controls(handles, case_id, index)
                frame, elapsed = adapter.tick()
                if type(frame) is not int or type(elapsed) not in (int, float) or not math.isfinite(elapsed):
                    raise ValueError('original Native frame/clock missing')
                if first_frame is None:
                    first_frame, first_time = frame, elapsed
                if frame != first_frame+index or not math.isclose(elapsed-first_time,index/20,abs_tol=.002):
                    raise ValueError('original Native frame/clock discontinuity')
                if runtime_capture_bound:
                    adapter.record_runtime_capture(frame, elapsed)
                actors = {name: adapter.actor_snapshot(handle, frame) for name,handle in handles.items()}
                row = {'frame': index, 'time_s': index/20,
                       'native_frame_id': frame, 'native_elapsed_seconds': elapsed,
                       'governing_device_readback': adapter.signal_readback(survey, frame),
                       **actors}
                rows.append(row)
                for name in CAMERAS:
                    ref = adapter.camera_frame(name, frame)
                    if not isinstance(ref, dict) or ref.get('frame') != frame or ref.get('channel') != name:
                        raise ValueError('original camera frame join differs')
                    path = _source_path(output, ref.get('source_path'))
                    if hashlib.sha256(path.read_bytes()).hexdigest() != ref.get('source_sha256'):
                        raise ValueError('original camera source hash differs')
                    media[name].append(ref)
                frame_map.append(frame,elapsed)
        actor_ids = {name: handles[name].id for name in handles}
        trace = {'case_id': case_id, 'map_sha256': survey['opendrive_sha256'],
                 'actor_ids': actor_ids, 'frames': rows}
        observation = measure(trace, survey)
        trace_path = output/'original-trace.json'
        trace_path.write_text(json.dumps(trace,indent=2)+'\n')
        index_path = output/'original-camera-index.json'
        index_path.write_text(json.dumps({'case_id':case_id,'channels':media},indent=2)+'\n')
        (output/'crossing-survey.json').write_bytes(raw_survey)
        (output/'original-map.xodr').write_bytes(raw_map)
        manifest = {'case_id':case_id,'source_kind':'original_native_acquisition',
                    'survey_sha256':survey_sha256,
                    'survey':{'path':'crossing-survey.json','sha256':survey_sha256},
                    'opendrive':{'path':'original-map.xodr','sha256':survey['opendrive_sha256']},
                    'trace':{'path':trace_path.name,'sha256':hashlib.sha256(trace_path.read_bytes()).hexdigest()},
                    'camera_index':{'path':index_path.name,'sha256':hashlib.sha256(index_path.read_bytes()).hexdigest()},
                    'frame_map':{'path':'video_frames.jsonl','sha256':hashlib.sha256((output/'video_frames.jsonl').read_bytes()).hexdigest()}}
        (output/'source-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
        completed = True
        return {'source_manifest':manifest,'observation':observation,
                'physical_acceptance_claimed':False}
    finally:
        try:
            try:
                if runtime_capture_bound:
                    adapter.close_runtime_capture(confirmed=completed)
            finally:
                if camera_bound:
                    adapter.close_cameras()
        finally:
            for name in ('other','ego'):
                if name in handles:
                    try:
                        adapter.emergency_stop(handles[name])
                    finally:
                        adapter.destroy(handles[name])

"""Independently compare saved C125751 measurements and fixed sources."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from delivery_audit import audit as audit_delivery
from entry_timing import ASSIGNMENT


def compare_verified(comparison_id, results, survey_hashes):
    plan = json.loads((Path(__file__).resolve().parent/'case-plan.json').read_text())
    matches = [row for row in plan['comparisons'] if row['comparison_id'] == comparison_id]
    if len(matches) != 1:
        raise ValueError('unknown exact crossing comparison')
    case_ids = matches[0]['case_ids']
    if set(results) != set(case_ids) or set(survey_hashes) != set(case_ids):
        raise ValueError('comparison exact cases differ')
    if len(set(survey_hashes.values())) != 1:
        raise ValueError('comparison original crossing survey changed')
    rows = {row['case_id']:row for row in plan['cases']}
    if any(case not in rows for case in case_ids):
        raise ValueError('comparison case plan missing')
    if any(results[case].get('case_id') != case for case in case_ids):
        raise ValueError('comparison saved case differs')
    observed = [results[case]['measured_values'] for case in case_ids]
    if any(value.get('statutory_applicability') != 'unresolved_official_device_exclusion_and_subsection_4'
           for value in observed):
        raise ValueError('comparison legal boundary changed')
    if comparison_id == 'precedence_response':
        if len({rows[case]['requested_entry_difference_s'] for case in case_ids}) != 1:
            raise ValueError('response comparison timing target changed')
        if len({value['observed_ego_response'] for value in observed}) != 2:
            raise ValueError('response comparison lacks measured response contrast')
        difference = 'measured ego entry relative to other full-body exit'
    elif comparison_id == 'approximately_same_time_brackets':
        if len({rows[case]['requested_ego_response'] for case in case_ids}) != 1:
            raise ValueError('timing comparison response target changed')
        if len({value['observed_ego_response'] for value in observed}) != 1:
            raise ValueError('timing comparison measured response changed')
        values = [value['ego_minus_other_upper_entry_s'] for value in observed]
        if not values[0] < values[1] < values[2]:
            raise ValueError('timing comparison lacks measured bracket ordering')
        difference = 'measured ego-minus-other upper entry time ordered across three probes'
    else:
        raise ValueError('unsupported exact crossing comparison')
    return {'assignment_id':ASSIGNMENT, 'comparison_id':comparison_id,
            'case_ids':case_ids, 'fixed_original_survey_sha256':survey_hashes[case_ids[0]],
            'measured_difference':difference, 'legal_judgment':'unresolved',
            'physical_acceptance_claimed':False}


def audit_comparison(comparison_id, attempts, surveys):
    if set(attempts) != set(surveys):
        raise ValueError('comparison attempt/survey cases differ')
    results, hashes = {}, {}
    for case,attempt in attempts.items():
        if not case.startswith(ASSIGNMENT+'__'):
            raise ValueError('foreign crossing case')
        audit_delivery(attempt,surveys[case])
        results[case] = json.loads((Path(attempt)/'result.json').read_text())
        hashes[case] = hashlib.sha256(Path(surveys[case]).read_bytes()).hexdigest()
    return compare_verified(comparison_id,results,hashes)


def _case_paths(rows):
    paths={}
    for item in rows:
        case,separator,path=item.partition('=')
        if (not separator or not case.startswith(ASSIGNMENT+'__') or
                not path or case in paths):
            raise ValueError('exact case=path audit binding required once per case')
        paths[case]=Path(path).resolve()
    return paths


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--comparison',required=True)
    parser.add_argument('--attempt',action='append',required=True)
    parser.add_argument('--survey',action='append',required=True)
    parser.add_argument('--output',required=True)
    args=parser.parse_args(argv)
    attempts,surveys=_case_paths(args.attempt),_case_paths(args.survey)
    output=Path(args.output).resolve()
    if output.exists() or any(output==attempt or attempt in output.parents
                              for attempt in attempts.values()):
        raise ValueError('fresh comparison output outside original attempts required')
    receipt=audit_comparison(args.comparison,attempts,surveys)
    receipt={'format':'worker-comparison-source-audit',**receipt,
             'attempt_result_sha256':{case:hashlib.sha256((attempt/'result.json').read_bytes()).hexdigest()
                                      for case,attempt in attempts.items()},
             'survey_sha256':{case:hashlib.sha256(path.read_bytes()).hexdigest()
                              for case,path in surveys.items()}}
    output.write_text(json.dumps(receipt,indent=2)+'\n')
    return receipt


if __name__=='__main__':
    main()

"""CARLA-facing adapter for source-gated C125751 original acquisition.

The reviewed survey must supply actor transforms, camera mounts and exact
control schedules. This adapter refuses absent sources and does not choose a
legal or desired physical outcome. The caller owns client/world restoration.
"""
from __future__ import annotations

import hashlib
import math
from pathlib import Path
from queue import Empty, Queue

from native_capture import CAMERAS

CASES = ('precedence', 'advance', 'timing_below', 'timing_inside', 'timing_above')
FRAME_COUNT = 900


def reviewed_schedule(survey, case_id):
    """Require continuous original-frame controls for both source actors."""
    suffix = case_id.rsplit('__', 1)[-1]
    if suffix not in CASES:
        raise ValueError('foreign exact control case')
    controls = survey.get('control_schedules')
    if not isinstance(controls, dict) or set(controls) != {'ego', 'other'}:
        raise ValueError('reviewed actor control schedules required')
    for name in ('ego', 'other'):
        rows = controls[name].get(suffix)
        if not isinstance(rows, list) or not rows:
            raise ValueError('reviewed exact actor control schedule missing')
        next_frame = 0
        for row in rows:
            if not isinstance(row, dict) or type(row.get('start_frame')) is not int or type(row.get('end_frame')) is not int:
                raise ValueError('reviewed control schedule frame bounds required')
            if row['start_frame'] != next_frame or row['end_frame'] < next_frame or row['end_frame'] >= FRAME_COUNT:
                raise ValueError('reviewed control schedule gap or overlap')
            throttle, brake, steer = (row.get(key) for key in ('throttle', 'brake', 'steer'))
            if (any(type(value) not in (int, float) or not math.isfinite(value)
                    for value in (throttle, brake, steer)) or
                    not 0 <= throttle <= 1 or not 0 <= brake <= 1 or not -1 <= steer <= 1 or
                    (throttle > 0 and brake > 0)):
                raise ValueError('reviewed actor control outside CARLA range')
            next_frame = row['end_frame'] + 1
        if next_frame != FRAME_COUNT:
            raise ValueError('reviewed control schedule incomplete')
    return suffix


class CarlaNativeAdapter:
    def __init__(self, client, carla, survey):
        self.client, self.carla, self.survey = client, carla, survey
        self.world = client.get_world()
        self.sensors = {}
        self.queues = {}
        self.output = None
        self.pipeline_capture = None

    def verify_map(self, survey, raw_map):
        if survey != self.survey:
            raise ValueError('reviewed crossing survey differs')
        actual = self.world.get_map().to_opendrive().encode()
        if hashlib.sha256(actual).hexdigest() != hashlib.sha256(raw_map).hexdigest():
            raise ValueError('CARLA OpenDRIVE readback differs')
        settings = self.world.get_settings()
        if not settings.synchronous_mode or not math.isclose(settings.fixed_delta_seconds,.05,abs_tol=1e-6):
            raise ValueError('CARLA synchronous 20 Hz world required')
        if not isinstance(survey.get('actor_sources'),dict) or set(survey['actor_sources']) != {'ego','other'}:
            raise ValueError('reviewed actor spawn sources required')
        if not isinstance(survey.get('camera_sources'),dict) or set(survey['camera_sources']) != set(CAMERAS):
            raise ValueError('reviewed four-camera mount sources required')
        controls = survey.get('control_schedules')
        if not isinstance(controls,dict) or set(controls) != {'ego','other'}:
            raise ValueError('reviewed actor control schedules required')
        if type(survey.get('governing_signal_actor_id')) is not int:
            raise ValueError('reviewed governing signal actor ID required')

    def _transform(self, source):
        if not isinstance(source,dict) or set(source) != {'location','rotation'}:
            raise ValueError('reviewed CARLA transform required')
        xyz, angles = source['location'], source['rotation']
        if (not isinstance(xyz,list) or len(xyz)!=3 or
                not isinstance(angles,list) or len(angles)!=3 or
                any(type(value) not in (int,float) or not math.isfinite(value)
                    for value in xyz+angles)):
            raise ValueError('finite reviewed CARLA transform required')
        return self.carla.Transform(self.carla.Location(*xyz),self.carla.Rotation(*angles))

    def spawn_actors(self, survey, case_id):
        reviewed_schedule(survey, case_id)
        spawned = {}
        try:
            for name in ('ego','other'):
                source = survey['actor_sources'][name]
                blueprint = self.world.get_blueprint_library().find(source['blueprint_id'])
                actor = self.world.try_spawn_actor(blueprint,self._transform(source['transform']))
                if actor is None:
                    raise ValueError('reviewed crossing actor spawn failed: '+name)
                spawned[name] = actor
            return spawned
        except Exception:
            for actor in reversed(list(spawned.values())):
                actor.destroy()
            raise

    def configure_cameras(self, ego, channels, *, fps, output):
        if tuple(channels) != CAMERAS or fps != 20:
            raise ValueError('original four-camera 20 Hz profile differs')
        self.output = Path(output)
        try:
            for name in CAMERAS:
                source = self.survey['camera_sources'][name]
                blueprint = self.world.get_blueprint_library().find('sensor.camera.rgb')
                for key in ('image_size_x','image_size_y','fov'):
                    blueprint.set_attribute(key,str(source[key]))
                blueprint.set_attribute('sensor_tick','0.05')
                sensor = self.world.spawn_actor(blueprint,self._transform(source['mount']),attach_to=ego)
                queue = Queue()
                sensor.listen(queue.put)
                self.sensors[name],self.queues[name] = sensor,queue
        except Exception:
            self.close_cameras()
            raise

    def start_runtime_capture(self, ego, case_id):
        """Start the pinned graph/evidence recorder on the original CARLA run."""
        if self.pipeline_capture is not None or self.output is None:
            raise ValueError('runtime capture already started or cameras unbound')
        from pipeline_capture import PipelineCapture
        self.pipeline_capture = PipelineCapture(
            self.client, ego, self.output, case_id,
            required_observations=self.survey.get('required_capture_atoms', ()))

    def record_runtime_capture(self, frame, elapsed):
        if self.pipeline_capture is None:
            raise ValueError('runtime capture was not started')
        self.pipeline_capture.capture(frame, elapsed)

    def close_runtime_capture(self, confirmed):
        if self.pipeline_capture is not None:
            try:
                self.pipeline_capture.close(confirmed=confirmed)
            finally:
                self.pipeline_capture = None

    def request_controls(self, handles, case_id, index):
        suffix = reviewed_schedule(self.survey, case_id)
        if type(index) is not int or not 0 <= index < FRAME_COUNT:
            raise ValueError('original control frame outside 900-frame plan')
        for name in ('ego','other'):
            schedule = self.survey['control_schedules'][name].get(suffix)
            if not isinstance(schedule,list):
                raise ValueError('reviewed exact actor control schedule missing')
            rows = [row for row in schedule if row['start_frame']<=index<=row['end_frame']]
            if len(rows)!=1:
                raise ValueError('reviewed control schedule gap or overlap')
            row=rows[0]
            values = [row.get(key) for key in ('throttle','brake','steer')]
            if (any(type(value) not in (int,float) or not math.isfinite(value) for value in values) or
                    not 0<=values[0]<=1 or not 0<=values[1]<=1 or not -1<=values[2]<=1):
                raise ValueError('reviewed actor control outside CARLA range')
            handles[name].apply_control(self.carla.VehicleControl(
                throttle=values[0],brake=values[1],steer=values[2]))

    def tick(self):
        frame = self.world.tick()
        snapshot = self.world.get_snapshot()
        if frame != snapshot.frame:
            raise ValueError('CARLA tick/snapshot frame differs')
        return frame,snapshot.timestamp.elapsed_seconds

    def actor_snapshot(self, actor, frame):
        location = actor.get_location()
        waypoint = self.world.get_map().get_waypoint(location,project_to_road=False)
        if waypoint is None:
            raise ValueError('original actor road readback missing')
        vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
        return {'id':actor.id,'road_id':waypoint.road_id,
                'body_vertices_xy_m':[[point.x,point.y] for point in vertices]}

    def signal_readback(self, survey, frame):
        signal = self.world.get_actor(survey['governing_signal_actor_id'])
        if signal is None:
            raise ValueError('original governing signal actor missing')
        state = str(signal.get_state()).split('.')[-1].lower()
        if state not in ('red','yellow','green','flashing','inoperative'):
            raise ValueError('original governing signal state unsupported')
        return state

    def camera_frame(self, name, frame):
        try:
            image = self.queues[name].get(timeout=10)
        except Empty as error:
            raise ValueError('original camera frame timeout') from error
        if image.frame != frame:
            raise ValueError('original camera callback frame differs')
        relative = Path('media')/name/f'{frame}.png'
        path = self.output/relative
        path.parent.mkdir(parents=True,exist_ok=True)
        image.save_to_disk(str(path))
        return {'channel':name,'frame':frame,'source_path':str(relative),
                'source_sha256':hashlib.sha256(path.read_bytes()).hexdigest()}

    def close_cameras(self):
        for name in reversed(CAMERAS):
            sensor = self.sensors.pop(name,None)
            if sensor is not None:
                try:
                    sensor.stop()
                finally:
                    sensor.destroy()
        self.queues.clear()

    def emergency_stop(self, actor):
        actor.apply_control(self.carla.VehicleControl(throttle=0,brake=1,steer=0))

    def destroy(self, actor):
        actor.destroy()

